code='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            min_r = min(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            shape = tuple(sorted((x-min_r, y-min_c) for x, y in cells))
            components.append((color, shape, cells))
    matching_colors = {}
    for color, shape, cells in components:
        if color != 1:
            matching_colors[shape] = color
    out = [row[:] for row in grid]
    for color, shape, cells in components:
        if color == 1 and shape in matching_colors:
            new_color = matching_colors[shape]
            for r, c in cells:
                out[r][c] = new_color
    return out
'''
